package br.edu.ifrn.sistemachamados.controller;
import br.edu.ifrn.sistemachamados.dto.request.*;import br.edu.ifrn.sistemachamados.dto.response.*;import br.edu.ifrn.sistemachamados.mapper.ApiMapper;import br.edu.ifrn.sistemachamados.model.*;import br.edu.ifrn.sistemachamados.model.enums.*;import br.edu.ifrn.sistemachamados.service.*;import jakarta.validation.*;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.*;
@RestController @RequestMapping("/chamados")public class ChamadoController{final ChamadoService s;final InteracaoService i;public ChamadoController(ChamadoService s,InteracaoService i){this.s=s;this.i=i;}Chamado e(AbrirChamadoRequest r){Chamado x=new Chamado();x.setTitulo(r.titulo());x.setDescricao(r.descricao());x.setLocal(r.local());x.setPrioridade(r.prioridade());Usuario u=new Usuario();u.setId(r.solicitanteId());x.setSolicitante(u);Categoria c=new Categoria();c.setId(r.categoriaId());x.setCategoria(c);return x;}@PostMapping public ResponseEntity<ChamadoResponse>post(@Valid@RequestBody AbrirChamadoRequest r){return ResponseEntity.status(201).body(ApiMapper.chamado(s.abrirChamado(e(r))));}@GetMapping public PageResponse<ChamadoResponse>list(@RequestParam(required=false)StatusChamado status,@RequestParam(required=false)Prioridade prioridade,@RequestParam(required=false)Long setorId,@RequestParam(required=false)Long categoriaId,@RequestParam(required=false)Long solicitanteId,@RequestParam(required=false)Long tecnicoId,@RequestParam(required=false)LocalDate dataInicio,@RequestParam(required=false)LocalDate dataFim,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer size,@RequestParam(required=false)String[] sort){if(dataInicio!=null&&dataFim!=null&&dataInicio.isAfter(dataFim))throw new br.edu.ifrn.sistemachamados.exception.DadosInvalidosException("Data inicial não pode ser posterior à data final.");return PageResponse.of(s.listar(status,prioridade,setorId,categoriaId,solicitanteId,tecnicoId,dataInicio==null?null:dataInicio.atStartOfDay(),dataFim==null?null:dataFim.atTime(LocalTime.MAX),WebSupport.page(page,size,sort)),ApiMapper::chamado);}@GetMapping("/{id}")public ChamadoDetalheResponse get(@PathVariable Long id){Chamado x=s.buscarPorId(id);return new ChamadoDetalheResponse(ApiMapper.chamado(x),i.listarPorChamado(id,PageRequest.of(0,50)).map(ApiMapper::interacao).getContent());}@PatchMapping("/{id}/assumir")public ChamadoResponse assumir(@PathVariable Long id,@Valid@RequestBody AssumirChamadoRequest r){return ApiMapper.chamado(s.assumirChamado(id,r.tecnicoId()));}@PatchMapping("/{id}/resolver")public ChamadoResponse resolver(@PathVariable Long id,@Valid@RequestBody ResolverChamadoRequest r){return ApiMapper.chamado(s.resolverChamado(id,r.tecnicoId(),r.solucao()));}@PatchMapping("/{id}/cancelar")public ChamadoResponse cancelar(@PathVariable Long id,@Valid@RequestBody CancelarChamadoRequest r){return ApiMapper.chamado(s.cancelarChamado(id,r.solicitanteId()));}@PostMapping("/{id}/interacoes")public ResponseEntity<InteracaoResponse>interacao(@PathVariable Long id,@Valid@RequestBody CriarInteracaoRequest r){return ResponseEntity.status(201).body(ApiMapper.interacao(i.registrarInteracao(id,r.autorId(),r.texto())));}}
